export interface PageMeta {
  /** Page title; falls back to a title-cased slug when absent. */
  title: string;
  /** Parsed publication date, or null when absent/invalid. */
  date: Date | null;
  /** Normalized, de-duplicated tag list. */
  tags: string[];
  /** Draft pages are excluded from builds unless --drafts is set. */
  draft: boolean;
  /** Layout name (a template in templates/layouts). */
  layout: string;
  /** Any additional frontmatter keys, passed through to templates. */
  extra: Record<string, unknown>;
}

export interface Page {
  sourcePath: string;
  /** Slug relative to the source root, without extension (posix separators). */
  slug: string;
  /** Site-absolute URL, e.g. "/posts/hello/". */
  url: string;
  /** Output path relative to outDir, e.g. "posts/hello/index.html". */
  outFile: string;
  meta: PageMeta;
  /** Rendered HTML of the markdown body (no layout applied). */
  html: string;
}

export interface SiteConfig {
  title: string;
  baseUrl: string;
  description: string;
}

export interface BuildOptions {
  sourceDir: string;
  templateDir: string;
  outDir: string;
  site?: Partial<SiteConfig>;
  includeDrafts?: boolean;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  skippedDrafts: number;
  outDir: string;
}

import matter from "gray-matter";
import type { PageMeta } from "./types.js";

const KNOWN_KEYS = new Set(["title", "date", "tags", "draft", "layout"]);

function normalizeDate(value: unknown): Date | null {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  if (typeof value === "string" || typeof value === "number") {
    const d = new Date(value);
    return Number.isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function normalizeTags(value: unknown): string[] {
  let raw: unknown[];
  if (Array.isArray(value)) raw = value;
  else if (typeof value === "string") raw = value.split(",");
  else return [];
  const seen = new Set<string>();
  for (const item of raw) {
    const tag = String(item).trim();
    if (tag) seen.add(tag);
  }
  return [...seen];
}

function normalizeDraft(value: unknown): boolean {
  if (typeof value === "boolean") return value;
  if (typeof value === "string") return value.trim().toLowerCase() === "true";
  return false;
}

export function titleFromSlug(slug: string): string {
  const last = slug.split("/").pop() ?? slug;
  return last
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim();
}

/**
 * Parse a markdown document with optional YAML frontmatter.
 * Returns normalized metadata and the markdown body.
 */
export function parseFrontmatter(
  raw: string,
  fallbackTitle = "Untitled"
): { meta: PageMeta; body: string } {
  const { data, content } = matter(raw);

  const extra: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(data)) {
    if (!KNOWN_KEYS.has(key)) extra[key] = value;
  }

  const meta: PageMeta = {
    title:
      typeof data.title === "string" && data.title.trim()
        ? data.title.trim()
        : fallbackTitle,
    date: normalizeDate(data.date),
    tags: normalizeTags(data.tags),
    draft: normalizeDraft(data.draft),
    layout:
      typeof data.layout === "string" && data.layout.trim()
        ? data.layout.trim()
        : "default",
    extra,
  };

  return { meta, body: content };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

/** Create a markdown renderer with syntax highlighting for fenced code blocks. */
export function createMarkdownRenderer(): (markdown: string) => string {
  const marked = new Marked(
    markedHighlight({
      langPrefix: "hljs language-",
      highlight(code, lang) {
        if (lang && hljs.getLanguage(lang)) {
          return hljs.highlight(code, { language: lang }).value;
        }
        return hljs.highlightAuto(code).value;
      },
    })
  );
  marked.setOptions({ gfm: true });

  return (markdown: string) => marked.parse(markdown) as string;
}

import Handlebars from "handlebars";
import fs from "node:fs/promises";
import path from "node:path";

const FALLBACK_LAYOUT = `<!doctype html>
<html>
<head><meta charset="utf-8"><title>{{page.title}} — {{site.title}}</title></head>
<body><main>{{{content}}}</main></body>
</html>`;

async function readDirIfExists(dir: string): Promise<string[]> {
  try {
    return await fs.readdir(dir);
  } catch {
    return [];
  }
}

/**
 * Handlebars-backed template engine.
 *
 * Directory layout:
 *   templates/
 *     layouts/   *.hbs   — page layouts, receive {{{content}}}, page, site, url
 *     partials/  *.hbs   — registered as partials by file name (no extension)
 */
export class TemplateEngine {
  private readonly hbs: typeof Handlebars;
  private readonly layouts = new Map<string, Handlebars.TemplateDelegate>();

  private constructor() {
    this.hbs = Handlebars.create();
    this.registerHelpers();
  }

  static async fromDir(templateDir: string): Promise<TemplateEngine> {
    const engine = new TemplateEngine();
    await engine.loadPartials(path.join(templateDir, "partials"));
    await engine.loadLayouts(path.join(templateDir, "layouts"));
    return engine;
  }

  /** In-memory construction, mainly for tests. */
  static fromSources(sources: {
    layouts?: Record<string, string>;
    partials?: Record<string, string>;
  }): TemplateEngine {
    const engine = new TemplateEngine();
    for (const [name, src] of Object.entries(sources.partials ?? {})) {
      engine.hbs.registerPartial(name, src);
    }
    for (const [name, src] of Object.entries(sources.layouts ?? {})) {
      engine.layouts.set(name, engine.hbs.compile(src));
    }
    return engine;
  }

  private registerHelpers(): void {
    this.hbs.registerHelper("formatDate", (value: unknown, format?: unknown) => {
      if (!(value instanceof Date) || Number.isNaN(value.getTime())) return "";
      if (format === "human") {
        return value.toLocaleDateString("en-US", {
          year: "numeric",
          month: "long",
          day: "numeric",
          timeZone: "UTC",
        });
      }
      return value.toISOString().slice(0, 10);
    });
    this.hbs.registerHelper("eq", (a: unknown, b: unknown) => a === b);
    this.hbs.registerHelper("join", (list: unknown, sep: unknown) =>
      Array.isArray(list) ? list.join(typeof sep === "string" ? sep : ", ") : ""
    );
  }

  private async loadPartials(dir: string): Promise<void> {
    for (const file of await readDirIfExists(dir)) {
      if (!file.endsWith(".hbs")) continue;
      const src = await fs.readFile(path.join(dir, file), "utf8");
      this.hbs.registerPartial(path.basename(file, ".hbs"), src);
    }
  }

  private async loadLayouts(dir: string): Promise<void> {
    for (const file of await readDirIfExists(dir)) {
      if (!file.endsWith(".hbs")) continue;
      const src = await fs.readFile(path.join(dir, file), "utf8");
      this.layouts.set(path.basename(file, ".hbs"), this.hbs.compile(src));
    }
  }

  hasLayout(name: string): boolean {
    return this.layouts.has(name);
  }

  /**
   * Render `context` with the named layout. Falls back to "default",
   * then to a built-in minimal layout.
   */
  render(layoutName: string, context: Record<string, unknown>): string {
    const layout =
      this.layouts.get(layoutName) ??
      this.layouts.get("default") ??
      this.hbs.compile(FALLBACK_LAYOUT);
    return layout(context);
  }
}

import type { Page, SiteConfig } from "./types.js";

export function escapeXml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function absoluteUrl(baseUrl: string, url: string): string {
  return `${baseUrl.replace(/\/+$/, "")}${url}`;
}

/** Generate an RSS 2.0 feed for dated, non-draft pages (newest first, max `limit`). */
export function generateRss(
  pages: Page[],
  site: SiteConfig,
  limit = 20
): string {
  const items = pages
    .filter((p) => !p.meta.draft && p.meta.date !== null)
    .sort((a, b) => (b.meta.date?.getTime() ?? 0) - (a.meta.date?.getTime() ?? 0))
    .slice(0, limit)
    .map((p) => {
      const link = absoluteUrl(site.baseUrl, p.url);
      return [
        "    <item>",
        `      <title>${escapeXml(p.meta.title)}</title>`,
        `      <link>${escapeXml(link)}</link>`,
        `      <guid>${escapeXml(link)}</guid>`,
        `      <pubDate>${p.meta.date!.toUTCString()}</pubDate>`,
        p.meta.tags.map((t) => `      <category>${escapeXml(t)}</category>`).join("\n"),
        `      <description><![CDATA[${p.html.replace(/]]>/g, "]]&gt;")}]]></description>`,
        "    </item>",
      ]
        .filter(Boolean)
        .join("\n");
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(site.title)}</title>
    <link>${escapeXml(site.baseUrl)}</link>
    <description>${escapeXml(site.description)}</description>
    <atom:link href="${escapeXml(absoluteUrl(site.baseUrl, "/feed.xml"))}" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>
`;
}

import fs from "node:fs/promises";
import path from "node:path";
import { parseFrontmatter, titleFromSlug } from "./frontmatter.js";
import { createMarkdownRenderer } from "./markdown.js";
import { TemplateEngine } from "./templates.js";
import { generateRss } from "./rss.js";
import type { BuildOptions, BuildResult, Page, SiteConfig } from "./types.js";

const DEFAULT_SITE: SiteConfig = {
  title: "My Site",
  baseUrl: "http://localhost:4000",
  description: "",
};

async function* walk(dir: string): AsyncGenerator<string> {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else if (entry.isFile()) yield full;
  }
}

function slugFor(sourceDir: string, file: string): string {
  return path
    .relative(sourceDir, file)
    .replace(/\.md$/i, "")
    .split(path.sep)
    .join("/");
}

function outputMapping(slug: string): { url: string; outFile: string } {
  if (slug === "index" || slug.endsWith("/index")) {
    const base = slug === "index" ? "" : slug.slice(0, -"/index".length);
    return {
      url: base ? `/${base}/` : "/",
      outFile: path.join(...(base ? base.split("/") : []), "index.html"),
    };
  }
  return {
    url: `/${slug}/`,
    outFile: path.join(...slug.split("/"), "index.html"),
  };
}

function tagSlug(tag: string): string {
  return tag
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function sortByDateDesc(pages: Page[]): Page[] {
  return [...pages].sort(
    (a, b) => (b.meta.date?.getTime() ?? 0) - (a.meta.date?.getTime() ?? 0)
  );
}

async function writeOut(outDir: string, relFile: string, content: string): Promise<void> {
  const target = path.join(outDir, relFile);
  await fs.mkdir(path.dirname(target), { recursive: true });
  await fs.writeFile(target, content, "utf8");
}

/** Build the site: markdown pages, tag index pages, RSS feed, static passthrough. */
export async function buildSite(options: BuildOptions): Promise<BuildResult> {
  const site: SiteConfig = { ...DEFAULT_SITE, ...options.site };
  const engine = await TemplateEngine.fromDir(options.templateDir);
  const renderMarkdown = createMarkdownRenderer();

  const pages: Page[] = [];
  const staticFiles: string[] = [];
  let skippedDrafts = 0;

  for await (const file of walk(options.sourceDir)) {
    if (!/\.md$/i.test(file)) {
      staticFiles.push(file);
      continue;
    }
    const slug = slugFor(options.sourceDir, file);
    const raw = await fs.readFile(file, "utf8");
    const { meta, body } = parseFrontmatter(raw, titleFromSlug(slug));
    if (meta.draft && !options.includeDrafts) {
      skippedDrafts++;
      continue;
    }
    const { url, outFile } = outputMapping(slug);
    pages.push({ sourcePath: file, slug, url, outFile, meta, html: renderMarkdown(body) });
  }

  const sorted = sortByDateDesc(pages);
  await fs.mkdir(options.outDir, { recursive: true });

  // Pages
  for (const page of pages) {
    const html = engine.render(page.meta.layout, {
      content: page.html,
      page: { ...page.meta, ...page.meta.extra, url: page.url },
      pages: sorted.map(pageContext),
      site,
    });
    await writeOut(options.outDir, page.outFile, html);
  }

  // Tag index pages
  const byTag = new Map<string, Page[]>();
  for (const page of sorted) {
    for (const tag of page.meta.tags) {
      const list = byTag.get(tag) ?? [];
      list.push(page);
      byTag.set(tag, list);
    }
  }

  const tagPages: string[] = [];
  for (const [tag, tagged] of byTag) {
    const url = `/tags/${tagSlug(tag)}/`;
    const html = engine.render("tag", {
      content: "",
      tag,
      page: { title: `Tagged: ${tag}`, url, tags: [], date: null },
      pages: tagged.map(pageContext),
      site,
    });
    await writeOut(options.outDir, path.join("tags", tagSlug(tag), "index.html"), html);
    tagPages.push(url);
  }

  // All-tags overview
  if (byTag.size > 0) {
    const tags = [...byTag.entries()]
      .map(([tag, list]) => ({ tag, slug: tagSlug(tag), count: list.length, url: `/tags/${tagSlug(tag)}/` }))
      .sort((a, b) => a.tag.localeCompare(b.tag));
    const html = engine.render("tags", {
      content: "",
      tags,
      page: { title: "Tags", url: "/tags/", tags: [], date: null },
      site,
    });
    await writeOut(options.outDir, path.join("tags", "index.html"), html);
  }

  // RSS feed
  await writeOut(options.outDir, "feed.xml", generateRss(sorted, site));

  // Static passthrough (non-markdown files in source dir)
  for (const file of staticFiles) {
    const rel = path.relative(options.sourceDir, file);
    const target = path.join(options.outDir, rel);
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.copyFile(file, target);
  }

  return { pages: sorted, tagPages, skippedDrafts, outDir: options.outDir };
}

function pageContext(page: Page): Record<string, unknown> {
  return {
    title: page.meta.title,
    date: page.meta.date,
    tags: page.meta.tags,
    draft: page.meta.draft,
    url: page.url,
    ...page.meta.extra,
  };
}

import http from "node:http";
import fs from "node:fs/promises";
import path from "node:path";
import chokidar from "chokidar";
import { WebSocketServer, WebSocket } from "ws";
import { buildSite } from "./build.js";
import type { BuildOptions } from "./types.js";

export const LIVE_RELOAD_PATH = "/__livereload";

export const RELOAD_SNIPPET = `<script>
(() => {
  const connect = () => {
    const ws = new WebSocket((location.protocol === "https:" ? "wss://" : "ws://") + location.host + "${LIVE_RELOAD_PATH}");
    ws.onmessage = (e) => { if (e.data === "reload") location.reload(); };
    ws.onclose = () => setTimeout(connect, 1000);
  };
  connect();
})();
</script>`;

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".xml": "application/xml; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".ico": "image/x-icon",
  ".txt": "text/plain; charset=utf-8",
  ".woff2": "font/woff2",
};

/** Inject the live-reload script before </body> (or append if absent). */
export function injectReloadScript(html: string): string {
  if (html.includes("</body>")) {
    return html.replace("</body>", `${RELOAD_SNIPPET}\n</body>`);
  }
  return html + RELOAD_SNIPPET;
}

async function resolveFile(outDir: string, urlPath: string): Promise<string | null> {
  const safe = path.normalize(decodeURIComponent(urlPath)).replace(/^(\.\.[/\\])+/, "");
  let file = path.join(outDir, safe);
  if (!file.startsWith(path.resolve(outDir) + path.sep) && file !== path.resolve(outDir)) {
    return null;
  }
  try {
    const stat = await fs.stat(file);
    if (stat.isDirectory()) file = path.join(file, "index.html");
    await fs.access(file);
    return file;
  } catch {
    return null;
  }
}

export interface DevServer {
  port: number;
  close: () => Promise<void>;
}

/** Start a dev server: initial build, static serving with reload injection, watch + rebuild. */
export async function serve(
  options: BuildOptions & { port?: number }
): Promise<DevServer> {
  const outDir = path.resolve(options.outDir);
  await buildSite(options);

  const server = http.createServer(async (req, res) => {
    const urlPath = (req.url ?? "/").split("?")[0] ?? "/";
    const file = await resolveFile(outDir, urlPath);
    if (!file) {
      res.writeHead(404, { "content-type": "text/html; charset=utf-8" });
      res.end(injectReloadScript("<h1>404 Not Found</h1>"));
      return;
    }
    const ext = path.extname(file).toLowerCase();
    const type = MIME[ext] ?? "application/octet-stream";
    if (ext === ".html") {
      const html = await fs.readFile(file, "utf8");
      res.writeHead(200, { "content-type": type });
      res.end(injectReloadScript(html));
    } else {
      res.writeHead(200, { "content-type": type });
      res.end(await fs.readFile(file));
    }
  });

  const wss = new WebSocketServer({ server, path: LIVE_RELOAD_PATH });
  const broadcast = (msg: string) => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  let rebuildTimer: NodeJS.Timeout | null = null;
  const watcher = chokidar.watch([options.sourceDir, options.templateDir], {
    ignoreInitial: true,
  });
  watcher.on("all", (event, file) => {
    if (rebuildTimer) clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(async () => {
      try {
        console.log(`[statik] ${event}: ${file} — rebuilding...`);
        await buildSite(options);
        broadcast("reload");
      } catch (err) {
        console.error("[statik] rebuild failed:", err);
      }
    }, 100);
  });

  const port = await new Promise<number>((resolve, reject) => {
    server.once("error", reject);
    server.listen(options.port ?? 4000, () => {
      const addr = server.address();
      resolve(typeof addr === "object" && addr ? addr.port : (options.port ?? 4000));
    });
  });

  console.log(`[statik] dev server: http://localhost:${port}`);

  return {
    port,
    close: async () => {
      if (rebuildTimer) clearTimeout(rebuildTimer);
      await watcher.close();
      wss.close();
      await new Promise<void>((resolve) => server.close(() => resolve()));
    },
  };
}

#!/usr/bin/env node
import { parseArgs } from "node:util";
import { pathToFileURL } from "node:url";
import path from "node:path";
import { buildSite } from "./build.js";
import { serve } from "./server.js";
import type { BuildOptions } from "./types.js";

export const HELP = `statik — static site generator

Usage:
  statik build [options]   Build the site
  statik serve [options]   Build, watch, and serve with live reload

Options:
  -s, --source <dir>      Markdown source directory      (default: content)
  -t, --templates <dir>   Handlebars template directory  (default: templates)
  -o, --out <dir>         Output directory               (default: dist-site)
  -p, --port <n>          Dev server port                (default: 4000)
      --drafts            Include pages marked draft: true
      --base-url <url>    Site base URL (used in RSS)    (default: http://localhost:4000)
      --title <title>     Site title                     (default: My Site)
      --description <s>   Site description for RSS
  -h, --help              Show this help
  -v, --version           Show version
`;

export interface CliCommand {
  command: "build" | "serve" | "help" | "version";
  options: BuildOptions & { port: number };
}

export function parseCliArgs(argv: string[]): CliCommand {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: true,
    options: {
      source: { type: "string", short: "s", default: "content" },
      templates: { type: "string", short: "t", default: "templates" },
      out: { type: "string", short: "o", default: "dist-site" },
      port: { type: "string", short: "p", default: "4000" },
      drafts: { type: "boolean", default: false },
      "base-url": { type: "string", default: "http://localhost:4000" },
      title: { type: "string", default: "My Site" },
      description: { type: "string", default: "" },
      help: { type: "boolean", short: "h", default: false },
      version: { type: "boolean", short: "v", default: false },
    },
  });

  const port = Number.parseInt(values.port!, 10);
  if (Number.isNaN(port) || port < 0 || port > 65535) {
    throw new Error(`Invalid port: ${values.port}`);
  }

  let command: CliCommand["command"];
  if (values.help) command = "help";
  else if (values.version) command = "version";
  else if (positionals[0] === "build" || positionals[0] === undefined) command = "build";
  else if (positionals[0] === "serve") command = "serve";
  else throw new Error(`Unknown command: ${positionals[0]}`);

  return {
    command,
    options: {
      sourceDir: path.resolve(values.source!),
      templateDir: path.resolve(values.templates!),
      outDir: path.resolve(values.out!),
      includeDrafts: values.drafts!,
      port,
      site: {
        baseUrl: values["base-url"]!,
        title: values.title!,
        description: values.description!,
      },
    },
  };
}

export async function main(argv = process.argv.slice(2)): Promise<void> {
  let cli: CliCommand;
  try {
    cli = parseCliArgs(argv);
  } catch (err) {
    console.error(`Error: ${err instanceof Error ? err.message : err}`);
    console.error(HELP);
    process.exitCode = 1;
    return;
  }

  switch (cli.command) {
    case "help":
      console.log(HELP);
      return;
    case "version": {
      const { readFile } = await import("node:fs/promises");
      const pkgPath = new URL("../package.json", import.meta.url);
      const pkg = JSON.parse(await readFile(pkgPath, "utf8")) as { version: string };
      console.log(pkg.version);
      return;
    }
    case "build": {
      const started = Date.now();
      const result = await buildSite(cli.options);
      console.log(
        `Built ${result.pages.length} page(s), ${result.tagPages.length} tag page(s)` +
          (result.skippedDrafts ? `, skipped ${result.skippedDrafts} draft(s)` : "") +
          ` -> ${cli.options.outDir} in ${Date.now() - started}ms`
      );
      return;
    }
    case "serve":
      await serve(cli.options);
      return;
  }
}

const isDirectRun =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;

if (isDirectRun) {
  main().catch((err) => {
    console.error(err instanceof Error ? err.message : err);
    process.exit(1);
  });
}

